/* --- вспомогательное для высокосимметричных моделей --- */
function orbit(seed,gens){const ops=closure(gens),out=[];seed.forEach(a=>ops.forEach(M=>{const q=mv(M,a.p);if(!out.some(b=>b.t===a.t&&Math.hypot(q[0]-b.p[0],q[1]-b.p[1],q[2]-b.p[2])<1e-3))out.push(A(a.t,...q))}));return out}
function bondsBy(atoms,rules){const b=[];for(let i=0;i<atoms.length;i++)for(let j=i+1;j<atoms.length;j++){const d=Math.hypot(...[0,1,2].map(k=>atoms[i].p[k]-atoms[j].p[k]));
  const r=rules.find(([a,c])=>(a===atoms[i].t&&c===atoms[j].t)||(c===atoms[i].t&&a===atoms[j].t));if(r&&d<r[2])b.push([i,j])}return b}
function idxNear(atoms,t,v){let best=-1,bd=1e9;atoms.forEach((a,i)=>{if(a.t!==t)return;const d=Math.hypot(a.p[0]-v[0],a.p[1]-v[1],a.p[2]-v[2]);if(d<bd){bd=d;best=i}});return best}
