const FAM=[['low','低对称'],['Cn','C<sub>n</sub>'],['Cnv','C<sub>nv</sub>'],['Cnh','C<sub>nh</sub>'],['Dn','D<sub>n</sub>'],['Dnh','D<sub>nh</sub>'],['Dnd','D<sub>nd</sub>'],['cubic','立方'],['ico','二十面体'],['lin','线形']];
