function proj(p){const cy=Math.cos(S.yaw),sy=Math.sin(S.yaw),cp=Math.cos(S.pitch),sp=Math.sin(S.pitch);const x=p[0]*cy-p[1]*sy,y=p[0]*sy+p[1]*cy,z=p[2];return {X:230+x*S.scale,Y:215-(z*cp+y*sp)*S.scale,D:y*cp-z*sp}}
