const ruN=(n,one,few,many)=>{const m10=n%10,m100=n%100;return m10===1&&m100!==11?one:(m10>=2&&m10<=4&&(m100<10||m100>=20)?few:many)};
const fx=s=>(s||'').replace(/R([xyz])/g,'R<sub>$1</sub>').replace(/([xyz])2/g,'$1²').replace(/;\s*/g,', ').replace(/,(?=\S)/g,', ').replace(/-/g,'−');

/* ===== линейные молекулы: классы бесконечных групп ===== */
const ZZ=[0,0,1];
const LIN_CT={
 'C∞v':{cols:['E','2C∞(φ)','…','∞σv'],kinds:['E','C',null,'s'],rows:[['A<sub>1</sub> ≡ Σ<sup>+</sup>',['1','1','…','1'],'z','x2+y2; z2'],['A<sub>2</sub> ≡ Σ<sup>−</sup>',['1','1','…','−1'],'Rz',''],
   ['E<sub>1</sub> ≡ Π',['2','2cos φ','…','0'],'(x,y); (Rx,Ry)','(xz,yz)'],['E<sub>2</sub> ≡ Δ',['2','2cos 2φ','…','0'],'','(x2-y2,xy)'],['E<sub>3</sub> ≡ Φ',['2','2cos 3φ','…','0'],'',''],['…',['…','…','…','…'],'','']],
   orb:{s:0,pz:0,dz2:0,px:2,py:2,dxz:2,dyz:2,dx2y2:3,dxy:3}},
 'D∞h':{cols:['E','2C∞(φ)','…','∞σv','i','2S∞(φ)','…','∞C₂'],kinds:['E','C',null,'s','i','S',null,'C2'],rows:[
   ['Σ<sub>g</sub><sup>+</sup>',['1','1','…','1','1','1','…','1'],'','x2+y2; z2'],['Σ<sub>g</sub><sup>−</sup>',['1','1','…','−1','1','1','…','−1'],'Rz',''],
   ['Π<sub>g</sub>',['2','2cos φ','…','0','2','−2cos φ','…','0'],'(Rx,Ry)','(xz,yz)'],['Δ<sub>g</sub>',['2','2cos 2φ','…','0','2','2cos 2φ','…','0'],'','(x2-y2,xy)'],['…',['…','…','…','…','…','…','…','…'],'',''],
   ['Σ<sub>u</sub><sup>+</sup>',['1','1','…','1','−1','−1','…','−1'],'z',''],['Σ<sub>u</sub><sup>−</sup>',['1','1','…','−1','−1','−1','…','1'],'',''],
   ['Π<sub>u</sub>',['2','2cos φ','…','0','−2','2cos φ','…','0'],'(x,y)',''],['Δ<sub>u</sub>',['2','2cos 2φ','…','0','−2','−2cos 2φ','…','0'],'',''],['…',['…','…','…','…','…','…','…','…'],'','']],
   orb:{s:0,dz2:0,pz:5,px:7,py:7,dxz:2,dyz:2,dx2y2:3,dxy:3}}};

/* ===== results of the server (sym.group / sym.state) as page objects ===== */
function mkL(r,Hm){return {id:r.id,cls:r.cls.map(c=>Object.assign({},c,{ops:c.idx.map(i=>Hm[i])}))}}
function applyState(r){S.H=r.H;S.L=mkL(r.L,S.H);S.linCT=S.L.id.lin?LIN_CT[S.L.id.name]:null;
  S.B=r.B?{Q:r.B.Q,opCol:r.B.opCol,colCls:r.B.colCls.map(i=>S.L.cls[i]),ct:r.B.ct}:null;S.orbIrr=r.orb||null;S.gamma=r.gamma||null;
  S.ops=r.ops?r.ops.map(o=>({M:S.H[o.h],name:o.name,cls:S.L.cls[o.ci]})):null;S.mul=r.mul||null;S.corr=r.corr}
/* messages for the error codes of sym.analyze */
const ERRT={empty_input:'输入为空。',bad_line:a=>'无法解析这一行：“'+a+'».',no_atoms:'没有找到“元素 x y z”格式的行。',empty_response:'返回为空。',too_big:'分子太大：本页最多可分析 150 个原子。',one_atom:'单个原子不是分子：它的点群是 K<sub>h</sub>（球），无需分析。',unsupported:a=>'找到点群 '+a+'，但本页暂不能显示这个点群。',align:'无法使找到的对称元素相互吻合。请尝试其他容差。',symmetrize:'无法对分子进行对称化。请尝试更大的容差。'};
function errText(r){const t=ERRT[r.err];return typeof t==='function'?t(r.arg):(t||r.err)}
/* ===== операции и анимация ===== */
function repOf(c){if(c.rep)return c.rep;const pa=S.L.id.pa;let best=c.ops[0],bf=info(best,pa);c.ops.forEach(o=>{const f=info(o,pa);if((f.k||0)<(bf.k||0)&&f.k)best=o,bf=f});return best}
function applyM(M,p,t){if(t<=0)return p;if(t>=1)return mv(M,p);const f=info(M,S.L.id.pa);
  if(f.t==='E')return p;
  if(f.t==='C')return mv(rot(f.ax,2*Math.PI*f.k/f.n*t),p);
  if(f.t==='i')return p.map(x=>x*(1-2*t));
  const scl=(q,n,k)=>{const d=dot(q,n);return q.map((x,i)=>x+n[i]*d*(k-1))};
  if(f.t==='s')return scl(p,f.ax,1-2*t);
  const th=2*Math.PI*f.k/f.n;const r=mv(rot(f.ax,th*Math.min(1,t*2)),p);return t<=.5?r:scl(r,f.ax,1-2*(t*2-1))}
