/* --- интерфейс --- */
(function(){const q=document.getElementById('molQ');if(!q)return;const dl=document.getElementById('molList'),msg=document.getElementById('molMsg');
  const say=(h,bad)=>{msg.innerHTML=h;msg.classList.toggle('bad',!!bad)};
  // каталог по группам
  const ORD=['C1','Cs','Ci','C2','C2h','C2v','C3v','C3h','C4v','C5v','S4','D2','D3','D2h','D3h','D4h','D5h','D6h','D7h','D8h','D2d','D3d','D4d','D5d','T','Td','Th','Oh','Ih','C∞v','D∞h'];
  const cat=document.getElementById('molCat');const byG={};MOLLIB.forEach(m=>(byG[m.g]=byG[m.g]||[]).push(m));
  [...ORD,...Object.keys(byG).filter(g=>!ORD.includes(g))].forEach(g=>{if(!byG[g])return;const row=document.createElement('div');row.className='cg';row.innerHTML='<b>'+prettyG(g)+'</b>';
    byG[g].forEach(m=>{const b=document.createElement('button');b.type='button';b.className='chip';b.textContent=m.ru;b.onclick=()=>{q.value=m.ru;fromLib()};row.appendChild(b)});cat.appendChild(row)});
  const sub=s=>{const m=s.match(/^(.*?)((?<=\])\d*[+-]|[+-])?$/);const D='₀₁₂₃₄₅₆₇₈₉',U='⁰¹²³⁴⁵⁶⁷⁸⁹';return m[1].replace(/\d/g,c=>D[c])+(m[2]?m[2].replace(/\d/g,c=>U[c]).replace('+','⁺').replace('-','⁻'):'')};
  const norm=s=>s.toLowerCase().replace(/ё/g,'').replace(/[\s()\[\]\-,]/g,'').replace(/[₀-₉]/g,c=>'0123456789'['₀₁₂₃₄₅₆₇₈₉'.indexOf(c)]);
  async function show(req,label,src,modelNote=''){const tol=+document.getElementById('tol').value;const r=await QC.api('sym.analyze',Object.assign({tol},req));
    if(r.err){say(errText(r),true);return}if(typeof label==='function')label=label(r.n);
    const g={name:r.name,family:'custom',mol:label,gens:r.gens,model:r.model,descents:[],custom:true,
      note:'点群由原子坐标确定'+(src?' ('+src+')':'')+'，容差 '+String(tol)+' Å；随后几何结构已对称化。'};
    if(modelNote)g.note+=' '+modelNote;
    await setGroup(g);say('点群：<b>'+prettyG(S.L.id.name)+'</b> — '+label+'。模型、类和特征标表显示在下方。');
    if(modelNote){const p=document.createElement('p');p.className='hint';p.textContent=modelNote;msg.appendChild(p)}
    document.getElementById('view').scrollIntoView({behavior:RM.matches?'auto':'smooth',block:'center'})}
  function fromLib(){const s=norm(q.value);if(!s){say('请输入名称或分子式。',true);return}
    let m=MOLLIB.find(x=>norm(x.ru)===s||norm(x.f)===s)||MOLLIB.find(x=>norm(x.ru).startsWith(s))||MOLLIB.find(x=>norm(x.ru).includes(s));
    if(!m){say('本页库中没有这个分子。请点击“在 PubChem 中查找”（需要英文名称和网络连接），或粘贴 XYZ 格式的坐标。',true);return}
    q.value=m.ru;show({atoms:m.a.map(x=>({t:x[0],p:x.slice(1)}))},(m.ru.includes(sub(m.f).replace(/[⁺⁻⁰-⁹]/g,''))?m.ru:m.ru+' ('+sub(m.f)+')'),'',m.note||'')}
  /* suggestions of the page's own style while typing (the browser list of every molecule opened on a click
     and looked foreign); nothing is shown for an empty field */
  const box=document.createElement('div');box.className='molSug';box.setAttribute('role','listbox');box.hidden=true;q.parentElement.appendChild(box);
  let hits=[],hi=-1;
  const pick=m=>{q.value=m.ru;close();fromLib()},close=()=>{box.hidden=true;hits=[];hi=-1;q.setAttribute('aria-expanded','false')};
  const mark=()=>[...box.children].forEach((c,i)=>c.classList.toggle('on',i===hi));
  function suggest(){const s=norm(q.value);if(!s){close();return}
    const a=MOLLIB.filter(x=>norm(x.ru).startsWith(s)||norm(x.f).startsWith(s)),b=MOLLIB.filter(x=>!a.includes(x)&&norm(x.ru).includes(s));
    hits=[...a,...b].slice(0,8);hi=-1;box.innerHTML='';if(!hits.length){close();return}
    hits.forEach((m,i)=>{const o=document.createElement('button');o.type='button';o.setAttribute('role','option');o.innerHTML='<span>'+m.ru.replace(/</g,'&lt;')+'</span><span class="f">'+sub(m.f)+'</span><span class="g">'+prettyG(m.g)+'</span>';
      o.onmousedown=e=>e.preventDefault();o.onclick=()=>pick(m);o.onmouseenter=()=>{hi=i;mark()};box.appendChild(o)});box.hidden=false;q.setAttribute('aria-expanded','true')}
  q.addEventListener('input',suggest);q.addEventListener('blur',()=>setTimeout(close,120));
  q.addEventListener('keydown',e=>{if(box.hidden)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();hi=(hi+(e.key==='ArrowDown'?1:hits.length-1)+(hi<0&&e.key==='ArrowUp'?1:0))%hits.length;mark()}
    else if(e.key==='Escape'){close()}else if(e.key==='Enter'&&hi>=0){e.preventDefault();e.stopImmediatePropagation();pick(hits[hi])}});
  document.getElementById('molGo').onclick=()=>{close();fromLib()};q.addEventListener('keydown',e=>{if(e.key==='Enter'){close();fromLib()}});
  document.getElementById('xyzGo').onclick=()=>{show({xyz:document.getElementById('xyz').value},n=>'自定义分子（'+n+' '+ruN(n,'个原子','个原子','个原子')+')','XYZ')};
  document.getElementById('pcGo').onclick=async()=>{const s=q.value.trim();if(!s){say('请在上面的输入框中输入分子的英文名称。',true);return}
    say('正在从 PubChem 加载…');const ac=new AbortController();const to=setTimeout(()=>ac.abort(),9000);
    try{const r=await fetch('https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/'+encodeURIComponent(s)+'/SDF?record_type=3d',{signal:ac.signal});clearTimeout(to);
      if(!r.ok){say('PubChem 未找到 3D 结构：“'+s.replace(/</g,'&lt;')+'”。请检查英文名称。',true);return}
      const txt=await r.text();return show({sdf:txt},s.replace(/</g,'&lt;')+' (PubChem)','PubChem，3D 构象')}
    catch(e){clearTimeout(to);say('无法连接 PubChem：此页面无法访问网络。请下载分子的 XYZ 格式坐标（例如从 PubChem 网站），然后粘贴到下面的输入框中。',true)}}
})();
